class Solution:
    def smallestBeautifulString(self, s: str, k: int) -> str:
        n = len(s)
        s = list(s)
        for i in range(n - 1, -1, -1):
            for o in range(ord(s[i]) - 96 + 1, k + 1):
                c = chr(96 + o)
                if (i >= 1 and s[i - 1] == c) or (i >= 2 and s[i - 2] == c):
                    continue
                res = s[:i] + [c]
                for j in range(i + 1, n):
                    for d in range(1, k + 1):
                        x = chr(96 + d)
                        if (j >= 1 and res[j - 1] == x) or (j >= 2 and res[j - 2] == x):
                            continue
                        res.append(x)
                        break
                return ''.join(res)
        return ""

