class Solution {
public:
    string smallestBeautifulString(string s, int k) {
        int n = s.size();
        for (int i = n - 1; i >= 0; i--) {
            for (int o = s[i] - 'a' + 1; o < k; o++) {
                char c = 'a' + o;
                if ((i >= 1 && s[i - 1] == c) || (i >= 2 && s[i - 2] == c)) continue;
                string res = s.substr(0, i) + c;
                for (int j = i + 1; j < n; j++)
                    for (char x = 'a'; ; x++) {
                        if ((j >= 1 && res[j - 1] == x) || (j >= 2 && res[j - 2] == x)) continue;
                        res += x; break;
                    }
                return res;
            }
        }
        return "";
    }
};

