class Solution {
    public String smallestBeautifulString(String s, int k) {
        int n = s.length();
        char[] a = s.toCharArray();
        for (int i = n - 1; i >= 0; i--) {
            for (int o = a[i] - 'a' + 1; o < k; o++) {
                char c = (char)('a' + o);
                if ((i >= 1 && a[i - 1] == c) || (i >= 2 && a[i - 2] == c)) continue;
                StringBuilder sb = new StringBuilder(s.substring(0, i)).append(c);
                for (int j = i + 1; j < n; j++)
                    for (char x = 'a'; ; x++) {
                        if ((j >= 1 && sb.charAt(j - 1) == x) || (j >= 2 && sb.charAt(j - 2) == x)) continue;
                        sb.append(x); break;
                    }
                return sb.toString();
            }
        }
        return "";
    }
}

