var smallestBeautifulString = function(s, k) {
    const n = s.length;
    const a = s.split('');
    for (let i = n - 1; i >= 0; i--) {
        for (let o = a[i].charCodeAt(0) - 96 + 1; o <= k; o++) {
            const c = String.fromCharCode(96 + o);
            if ((i >= 1 && a[i - 1] === c) || (i >= 2 && a[i - 2] === c)) continue;
            const res = a.slice(0, i);
            res.push(c);
            for (let j = i + 1; j < n; j++)
                for (let d = 1; ; d++) {
                    const x = String.fromCharCode(96 + d);
                    if ((j >= 1 && res[j - 1] === x) || (j >= 2 && res[j - 2] === x)) continue;
                    res.push(x); break;
                }
            return res.join('');
        }
    }
    return "";
};
